    if len(points) < 3:
        return False

    def cross(a, b, c):
        (x1, y1), (x2, y2), (x3, y3) = a, b, c
        return (y2 - y1) * (x3 - x2) - (y3 - y2) * (x2 - x1)

    sign = 0
    n = len(points)
