def count_paths(grid):
    from functools import lru_cache

    m, n = len(grid), len(grid[0])
    if grid[0][0] == 1 or grid[m - 1][n - 1] == 1:
        return 0

    @lru_cache(maxsize=None)
    def dp(row, col):
        if row == m - 1 and col == n - 1:
            return 1
        if grid[row][col] == 1:
            return 0
        total = 0
        if row + 1 < m:
            total += dp(row + 1, col)
        if col + 1 < n:
            total += dp(row, col + 1)
        return total

    return dp(0, 0)
```

