def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
    red_start = (tick // (red_duration + green_duration)) * (red_duration + green_duration)
    window = (arrivals[0], arrivals[-1]) if arrivals else (0, 0)
    for cycle in range(0, window[1] + green_duration + red_duration, red_duration + green_duration):
        start = cycle
        end = start + red_duration
        if end > window[1]:
            end = window[1] + 1
        for tick in range(start, end + green_duration):
            if tick < window[0]:
                continue
            yield tick

    def phase_of_tick(tick):
        cycle = tick // (red_duration + green_duration)
        offset = tick - cycle * (red_duration + green_duration)
        if offset < red_duration:
            return 'RED'
        return 'GREEN'

    result = []
    for arrival in arrivals:
        for tick in pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
            if tick >= arrival and phase_of_tick(tick) == 'RED':
                result.append(tick)
                break
    return result
```

