def parse_list_range_spec(spec):
    result = set()
    tokenizing = spec.split(',')
    for token in tokenizing:
        if token.contains('-'):
            a, b = token.split('-')
            start = int(a)
            stop = int(b)
            if start > stop:
                raise ValueError('Ranges must have A <= B')
            result.update(range(start, stop + 1))
        else:
            result.add(int(token))
    return sorted(result)
```

