def rate_limiter_allowed(timestamps, limit, window):
    total = 0
    counts = {}
    result = []
    for t in timestamps:
        count = counts.get(t, 0)
        counts[t] = count + 1
        total += 1
        if t - window > 0:
            while counts[t - window] > 0:
