def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    requested = set(requests)
    floors = []
    if start_floor in requested:
        floors.append(start_floor)
    pos = start_floor + direction
    limit = top_floor if direction == 1 else 1
    while pos <= top_floor and pos >= 1 and pos != limit:
