class FloodState:
    def __init__(self, grid, rows, cols, sr, sc, out, old):
        self.grid = grid
        self.rows = rows
        self.cols = cols
        self.sr, self.sc = sr, sc
        self.out = out
        self.old = old

def flood_fill(grid, sr, sc, new_value):
    if isinstance(grid, FloodState):
        state = grid
    else:
        rows = len(grid)
        cols = len(grid[0]) if rows else 0
        state = FloodState(grid, rows, cols, sr, sc, [['' for _ in range(cols)] for _ in range(rows)], grid[sr][sc])
    if state.out[sr][sc] == '':
        state.out[sr][sc] = str(new_value)
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 or dc == 0:
                    r, c = sr + dr, sc + dc
                    if 0 <= r < state.rows and 0 <= c < state.cols:
                        if state.grid[r][c] == state.old:
