def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    stops = [start_floor]
    current = start_floor

    def is_stopping_floor(f): return f in requests
    if direction == 1:
        for current in range(start_floor + 1, top_floor + 1):
            if is_stopping_floor(current):
